'use strict';
// Incremental business-flow extension. Existing demo data and base handlers remain.
const F=GilliganFlow,oldShow=show,oldRenderResult=renderResult,oldOpenReview=openReview;
let inputType='material',selectedRefs=new Set(),pendingInput=null,pendingParent=null;
db.usage=Array.isArray(db.usage)?db.usage:[];
document.querySelector('.demo-banner').textContent='业务流程演示 V2 · 合成素材与模拟AI结果；生成、评分、效果均非真实验证。记录只保存在当前浏览器。';
const typeNames={material:'素材／草稿',draft:'已有成稿',topic:'只有选题'};
const sourceTypeNames=F.types;
const nav=document.querySelector('.sidebar nav');
nav.insertAdjacentHTML('beforeend','<button class="nav-item" data-page="knowledge" aria-label="资料与爆款"><span>⌕</span><span class="nav-label">资料与爆款</span></button>');
document.querySelector('main').insertAdjacentHTML('beforeend','<section id="knowledge-page" class="hidden"></section><section id="usage-page" class="hidden"></section>');
document.querySelector('#gilligan-form .business-switch').outerHTML='<div class="business-switch" aria-label="输入内容类型">'+Object.entries(typeNames).map(([k,v])=>'<button class="business-tab" data-input-type="'+k+'" aria-pressed="'+(k==='material')+'"><span class="tab-icon">'+({material:'材',draft:'稿',topic:'题'})[k]+'</span><span><strong>'+v+'</strong><small>'+({material:'先评估素材，或直接按吉利根表达改写',draft:'检查学问与表达，再按问题改稿',topic:'先找到依据，再形成口播稿或初稿'})[k]+'</small></span></button>').join('')+'</div><div class="task-flow"><span>材料与目标</span><span>检索依据</span><span>评估／改写</span><span>终稿与来源</span></div>';
$('#material-label').innerHTML='素材或草稿 <strong>必填</strong>';
$('#task-form fieldset').insertAdjacentHTML('afterbegin','<div class="entry-intent"><label>本次要做什么<select id="intent"><option value="evaluate">先评估，再决定如何改写</option><option value="rewrite">直接改写</option></select></label><label>产出形式<select id="output-type"><option value="speech">短视频口播稿</option><option value="draft">文案初稿</option></select></label></div>');
document.querySelector('.test-control').insertAdjacentHTML('beforebegin','<div class="selected-context"><strong>本次参考</strong><p id="selected-context" class="muted">两层合成知识示例随任务检索；可补充选择爆款或已审效果参考。</p><button class="button ghost" type="button" id="open-knowledge">查资料／找爆款并带入</button></div>');
document.body.insertAdjacentHTML('beforeend','<dialog id="prepare-dialog"><h2>改写准备</h2><p class="muted">承接Skill风格指纹与保留项；以下为可编辑的模拟分析，不是实际模型结论。</p><div id="prepare-body"></div><div class="button-row"><button id="prepare-run" class="button primary">按这些边界改写</button><button id="prepare-cancel" class="button ghost">返回调整</button></div></dialog><dialog id="effects-dialog"><h2 id="effects-title">提交团队参考</h2><div id="effects-fields"></div><p id="effects-error" class="field-error" role="alert"></p><div class="button-row"><button id="effects-save" class="button primary">确认</button><button id="effects-cancel" class="button ghost">取消</button></div></dialog>');
show=function(p){oldShow(['knowledge','usage'].includes(p)?'none':p);$('#knowledge-page').classList.toggle('hidden',p!=='knowledge');$('#usage-page').classList.toggle('hidden',p!=='usage');if(p==='knowledge')renderKnowledge();if(p==='usage')renderUsage();$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));};
function bindNavigation(){$$('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));}
function allSources(){return [...F.catalog,...F.approved(db.reviews,business())];}
function refsFor(input){if(input.parentSources)return input.parentSources;const ss=allSources(),base=input.inputType==='topic'?F.retrieve(input.material,'all',db.reviews).filter(s=>s.type==='course'||s.type==='book'):F.catalog.filter(s=>s.type==='course'||s.type==='book');if(input.inputType==='topic'&&!base.length)return [];const ids=new Set([...base.map(s=>s.id),...selectedRefs]);return ss.filter(s=>ids.has(s.id));}
function updateContext(){$('#selected-context').textContent=selectedRefs.size?'已选择 '+selectedRefs.size+' 条额外参考；课程与书籍合成依据仍随任务检索。':'两层合成知识示例随任务检索；可补充选择爆款或已审效果参考。';}
function setInputType(k){inputType=k;$$('[data-input-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.inputType===k)));$('#material-label').innerHTML=typeNames[k]+' <strong>必填</strong>';$('#intent').innerHTML=k==='topic'?'<option value="create">根据选题查依据并起稿</option>':'<option value="evaluate">先评估，再决定如何改写</option><option value="rewrite">直接改写</option>';$('#submit').textContent=k==='topic'?'查依据并起稿':'开始评估';}
$$('[data-input-type]').forEach(b=>b.onclick=()=>setInputType(b.dataset.inputType));
$('#intent').onchange=()=>$('#submit').textContent=$('#intent').value==='evaluate'?'开始评估':'分析原稿并改写';
$('#open-knowledge').onclick=()=>show('knowledge');
$('#task-form').onsubmit=e=>{e.preventDefault();const i={business:business(),inputType,operation:$('#intent').value,material:$('#material').value.trim(),requirements:$('#requirements').value.trim(),retain:$('#retain').value.trim(),outputType:$('#output-type').value,scenario:$('#scenario').value};if(i.operation==='rewrite')prepare(i);else run(i);};
function prepare(i){pendingInput=i;pendingParent=i._parent||null;const a=F.analyze(i);$('#prepare-body').innerHTML='<dl class="fingerprint"><dt>叙述视角</dt><dd>'+esc(a.perspective)+'</dd><dt>情绪与节奏</dt><dd>'+esc(a.tone+'；'+a.rhythm)+'</dd><dt>结构</dt><dd>'+esc(a.structure)+'</dd><dt>核心洞察</dt><dd>'+esc(a.insight)+'</dd></dl><label class="field">保留项<textarea id="prepare-retain">'+esc(a.keep)+'</textarea></label><label class="field">禁止改动项<textarea id="prepare-prohibited">'+esc(a.prohibited)+'</textarea></label><p class="muted">本次要求：'+esc(i.requirements||'无额外要求')+'</p>';$('#prepare-dialog').showModal();}
$('#prepare-cancel').onclick=()=>$('#prepare-dialog').close();$('#prepare-run').onclick=()=>{const i={...pendingInput,retain:$('#prepare-retain').value,prohibited:$('#prepare-prohibited').value};$('#prepare-dialog').close();run(i,pendingParent);};
run=async function(input,parent=null){if(busy)return;busy=true;$('#submit').disabled=true;show('result');$('#result-page').innerHTML='<div class="live-status"><span class="step">模拟处理中</span><h1>检索依据并检查任务边界</h1><p>关联原稿、保留项、知识来源与本轮要求；不运行真实模型。</p></div>';const start=performance.now();await new Promise(r=>setTimeout(r,450));const ss=refsFor(input),result=F.compose(input,ss);const usage={id:'attempt-'+Date.now(),business:input.business,owner:user(),operation:input.operation,status:result.status,durationMs:Math.round(performance.now()-start),at:new Date().toISOString(),tokens:null,cost:null};db.usage.unshift(usage);persist();busy=false;$('#submit').disabled=false;
if(result.status!=='completed'){$('#result-page').innerHTML='<div class="notice blocked"><h1>'+({INSUFFICIENT_EVIDENCE:'依据不足',MISSING_INPUT:'请补充材料',QUOTA_EXCEEDED:'额度不足',BRIDGE_OFFLINE:'服务暂不可用'})[result.code]+'</h1><p>'+esc(result.reason)+'</p><p class="muted">未补造内容，未创建成功成稿；本次尝试已计入本地模拟用量。</p><button class="button primary" id="retry-input">返回原输入</button></div>';$('#retry-input').onclick=()=>show('creator');return;}
if(parent){current=parent;current.versions.push({version:current.version,content:current.content,assessment:current.assessment,stage:current.stage});current.version++;current.modifications++;current.content=result.content;current.stage='final';current.operation='rewrite';current.title=result.title;current.analysis=result.analysis;current.issues=result.issues;current.sources=result.sources;current.updatedAt=new Date().toISOString();current.lastChange=input.revision||input.direction||'按评估建议改写';}else{current={id:'demo-'+Date.now()+'-'+Math.random().toString(16).slice(2),business:input.business,owner:user(),inputType:input.inputType,operation:input.operation,stage:input.operation==='evaluate'?'assessment':'final',original:input.material,content:input.operation==='evaluate'?input.material:result.content,title:result.title,assessment:result.assessment,issues:result.issues,analysis:result.analysis,sources:result.sources,requirements:input.requirements||'',retain:input.retain||'',outputType:input.outputType,prohibited:input.prohibited||'',version:1,modifications:0,versions:[],liked:false,updatedAt:new Date().toISOString(),modelCalled:false};db.records.unshift(current);}persist();renderResult();};
assessment=function(a){if(!a)return '';return '<div class="axis-grid"><div class="score-card"><h3>学问忠实度</h3><span class="tag">'+esc(a.fidelity.level)+'</span><p>'+esc(a.fidelity.reason)+'</p></div><div class="score-card"><h3>表达贴近度</h3><span class="tag">'+esc(a.expression.level)+'</span><p>'+esc(a.expression.reason)+'</p></div></div>';};
sources=function(ss){return ss.map(s=>'<article class="source-card"><span class="tag">'+esc(sourceTypeNames[s.type]||'旧版合成来源')+'</span><h3>'+esc(s.title)+'</h3><details><summary>查看来源与使用边界</summary><p>'+esc(s.text)+'</p><p>'+esc(s.locator)+'</p><p>'+esc(s.citation||'合成参照')+' · 仅模拟</p><p class="muted">'+esc(s.usage)+'</p></details><small>'+ (s.used?'已用于本轮模拟；非真实模型采用证据':'候选参考')+'</small></article>').join('');};
function issueHTML(r){return '<section class="sentence-evidence"><h2>逐句诊断与来源</h2><p class="muted">仅演示核对方式。缺依据不等于错误；只有合成原文逐字对应才标对应，不宣称为吉利根原话。</p>'+ (r.stage==='assessment'?(r.issues||F.evidence(r.original||r.content,r.sources)):F.evidence(r.content,r.sources)).map((x,n)=>'<details class="issue"><summary>第 '+(n+1)+' 句 · '+esc(x.kind||'依据待核对')+'</summary><blockquote>'+esc(x.fragment)+'</blockquote><p>理由／建议：'+esc(x.suggestion)+'</p><button class="button ghost" data-source="'+esc(x.sourceId)+'">查看对应来源</button><p class="muted">'+esc(x.source)+'</p></details>').join('')+'</section>';}
renderResult=function(){oldRenderResult();const r=current;if(!r)return;const own=r.owner===user(),isAssessment=r.stage==='assessment'||r.operation==='evaluate';const main=$('#result-page .result-columns > div');const h=$('#result-page h1');h.textContent=isAssessment?'评估报告':'终稿与来源';
$('#result-page .result-top').insertAdjacentHTML('afterend','<div class="task-flow"><span>'+esc(typeNames[r.inputType]||'历史材料')+'</span><span>来源已关联（模拟）</span><span>'+(isAssessment?'两轴诊断':'改写与校验')+'</span><span>第 '+r.version+' 版</span></div><details class="task-summary"><summary>本次任务与原稿</summary><p>产出：'+esc(r.outputType==='draft'?'文案初稿':'口播稿')+'；要求：'+esc(r.requirements||'未填写')+'</p><p>保留：'+esc(r.retain||'无额外指定')+'</p><div class="review-body">'+esc(r.original||r.content)+'</div></details>');
if(isAssessment){main.innerHTML='<h2>两轴评价报告</h2>'+assessment(r.assessment)+issueHTML(r)+'<div class="button-row"><button id="rewrite-by-report" class="button primary">按建议改写</button><button id="see-directions" class="button ghost">先看改写方向</button></div><div id="directions-box"></div>';const rv=$('#result-page .revise');if(rv)rv.remove();$('#submit-team').remove();const personal=$('#personal');if(personal)personal.remove();$('#rewrite-by-report').onclick=()=>prepare({_parent:r,...r,material:r.original||r.content,operation:'rewrite',parentSources:r.sources});$('#see-directions').onclick=()=>renderDirections(r);
}else{const out=$('#output');if(out){out.insertAdjacentHTML('beforebegin','<label class="field">文案标题<input id="final-title" value="'+esc(r.title)+'"></label>');out.insertAdjacentHTML('afterend',issueHTML(r));}if($('#save-edit'))$('#save-edit').onclick=()=>{r.title=$('#final-title').value.trim()||r.title;saveVersion($('#output').value,'手动编辑');};if($('#revise'))$('#revise').onclick=()=>{const revision=$('#revision').value.trim();if(!revision){notify('请填写本轮修改要求');return;}run({business:r.business,inputType:r.inputType,operation:'rewrite',material:$('#output').value,requirements:r.requirements,retain:r.retain,revision,scenario:'available',parentSources:r.sources},r);};if($('#submit-team'))$('#submit-team').onclick=()=>effectDialog(r);}
$$('[data-source]').forEach(b=>b.onclick=()=>openSource(allSources().find(s=>s.id===b.dataset.source)||r.sources.find(s=>s.id===b.dataset.source)));bindNavigation();};
function renderDirections(r){$('#directions-box').innerHTML='<h2>选择改写方向</h2><p class="muted">以下是结构方案示例；选择后仍保留原稿核心洞察和来源边界。</p>'+['保留原结构，降低说教感','用问题切入，保留关键转折','压缩为短口播，突出一个行动'].map((t,n)=>'<article class="source-card"><h3>方向 '+(n+1)+' · '+t+'</h3><button class="button ghost" data-direction="'+n+'">按方向 '+(n+1)+' 改写</button></article>').join('');$$('[data-direction]').forEach(b=>b.onclick=()=>run({business:r.business,inputType:r.inputType,operation:'rewrite',material:r.original||r.content,retain:r.retain,requirements:r.requirements,direction:b.parentElement.querySelector('h3').textContent,scenario:'available',parentSources:r.sources},r));}
function openSource(s){if(!s)return;$('#review-detail').innerHTML='<h2>'+esc(s.title)+'</h2><span class="tag">'+esc(sourceTypeNames[s.type]||'演示来源')+'</span><p>'+esc(s.locator)+'</p><div class="review-body">'+esc(s.text)+'</div><p>'+esc(s.usage)+'</p><p>引用状态：'+esc(s.citation||'待核对')+'。不能冒充真实吉利根原话。</p>';$('#review-dialog').showModal();}
function renderKnowledge(){const q=$('#knowledge-query')?.value||'',type=$('#source-type')?.value||'all';$('#knowledge-page').innerHTML='<header class="page-header"><div><p class="eyebrow">知识与参考</p><h1>资料与爆款</h1></div><button class="button primary" id="bring-back">将选择带入任务</button></header><p class="muted">课程／书籍支持观点核对，成品／爆款只作表达参照。所有条目均为合成演示；已撤销的团队参考不会出现。</p><div class="filter-row content-panel"><label>选题或关键词<input id="knowledge-query" placeholder="例如：变化、压力、感受" value="'+esc(q)+'"></label><label>资料类型<select id="source-type"><option value="all">全部资料</option>'+Object.entries(sourceTypeNames).map(([k,v])=>'<option value="'+k+'" '+(type===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label></div><p class="muted" id="knowledge-count"></p><div id="knowledge-results"></div>';function list(){const rs=F.retrieve($('#knowledge-query').value,$('#source-type').value,db.reviews);$('#knowledge-count').textContent=rs.length+' 条合成候选 · 已选择 '+selectedRefs.size+' 条';$('#knowledge-results').innerHTML=rs.length?rs.map(s=>'<article class="source-card"><span class="tag">'+esc(sourceTypeNames[s.type])+'</span><h2>'+esc(s.title)+'</h2><p>'+esc(s.relevance)+'</p><p>'+esc(s.locator)+'</p>'+(s.effects?'<p class="muted">人工效果声明（模拟）：'+effectText(s.effects)+'</p>':'')+'<div class="button-row"><button class="button ghost" data-view-source="'+s.id+'">查看内容与来源</button><button class="button '+(selectedRefs.has(s.id)?'primary':'ghost')+'" data-pick="'+s.id+'">'+(selectedRefs.has(s.id)?'取消选择':'选作本次参考')+'</button></div></article>').join(''):'<div class="empty">未找到匹配的演示依据。请换关键词或补充授权材料，不会自动编造内容。</div>';$$('[data-view-source]').forEach(b=>b.onclick=()=>openSource(allSources().find(s=>s.id===b.dataset.viewSource)));$$('[data-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.pick;selectedRefs.has(id)?selectedRefs.delete(id):selectedRefs.add(id);list();});}$('#knowledge-query').oninput=list;$('#source-type').onchange=list;$('#bring-back').onclick=()=>{updateContext();show('creator');};list();}
const saleNames={unverified:'成交未验证',zero:'0单','1-9':'1–9单','10-19':'10–19单','20+':'20单及以上'};
function effectText(e){return esc([e.quality?'内容质量认可':'',e.viral?e.platform+'单作品已达1000赞（人工确认）':'',saleNames[e.sales]||'成交未验证'].filter(Boolean).join('；'));}
function effectDialog(r){const direct=admin();$('#effects-title').textContent=direct?'直接纳入团队参考':'提交团队审核';$('#effects-fields').innerHTML='<p>文案：'+esc(r.title)+' · 第 '+r.version+' 版</p><label class="checkline"><input type="checkbox" id="effect-quality" checked>内容质量认可（不等于效果已验证）</label><label class="checkline"><input type="checkbox" id="effect-viral">单作品已达到千赞，可作爆款参考</label><label class="field">确认的平台<select id="effect-platform"><option value="">未选择</option><option>视频号</option><option>小红书</option><option>抖音</option></select></label><label class="checkline"><input type="checkbox" id="effect-confirm">我已人工核对该单平台、单作品达到1000赞（仅演示声明）</label><label class="field">实际成交档位<select id="effect-sales">'+Object.entries(saleNames).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><label class="field">说明／链接（可选）<textarea id="effect-note" placeholder="可以补充判断依据，不强制填详细运营数据"></textarea></label><p class="muted">确认人：'+esc(user())+'；提交内容按当前版本冻结。未验证不等于0，质量认可不自动成为效果范例。</p>';$('#effects-error').textContent='';$('#effects-dialog').showModal();$('#effects-save').onclick=()=>{const e={quality:$('#effect-quality').checked,viral:$('#effect-viral').checked,platform:$('#effect-platform').value,confirmed:$('#effect-confirm').checked,sales:$('#effect-sales').value,note:$('#effect-note').value,confirmer:user(),confirmedAt:new Date().toISOString()};const error=F.validateEffects(e);if(error){$('#effects-error').textContent=error;return;}const existing=db.reviews.find(x=>x.recordId===r.id&&x.sourceVersion===r.version&&['pending','approved'].includes(x.status));if(existing){$('#effects-error').textContent='本版已有提交或已纳入，请到提交记录查看。';return;}const s=A.snapshot(r,user(),direct);s.effects=e;s.sources=JSON.parse(JSON.stringify(r.sources));db.reviews.unshift(s);persist();$('#effects-dialog').close();renderResult();notify(direct?'管理员已直接纳入；后续可在资料与爆款查找、选用。':'已提交等待审核，个人标记不变；通过后才供团队参考。');};}
$('#effects-cancel').onclick=()=>$('#effects-dialog').close();
openReview=function(x){oldOpenReview(x);$('#review-detail').insertAdjacentHTML('beforeend','<div class="notice"><strong>人工质量与效果声明</strong><p>'+ (x.effects?effectText(x.effects):'旧版演示提交：无效果信息，不能作为已验证效果样本')+'</p><p>确认人：'+esc(x.effects?.confirmer||'未记录')+'；确认时间：'+esc(x.effects?.confirmedAt||'未记录')+'</p><p>'+esc(x.effects?.note||'无额外说明')+'</p></div>');};
function renderUsage(){const rows=db.usage.filter(x=>x.business===business()&&(admin()||x.owner===user()));$('#usage-page').innerHTML='<header class="page-header"><div><p class="eyebrow">仅本地演示统计</p><h1>使用情况</h1></div></header><p class="muted">成员仅看本人；演示管理员看本业务。真实鉴权和费用尚未接入，模拟次数不等于AI调用次数。</p><div class="metric-grid"><div class="score-card"><h2>任务尝试</h2><strong>'+rows.length+'</strong></div><div class="score-card"><h2>完成</h2><strong>'+rows.filter(x=>x.status==='completed').length+'</strong></div><div class="score-card"><h2>阻断／失败</h2><strong>'+rows.filter(x=>x.status!=='completed').length+'</strong></div><div class="score-card"><h2>模型消耗</h2><strong>未调用</strong><p>Token未知；实际费用未知</p></div></div>'+ (rows.length?rows.map(x=>'<article class="history-row"><div><h2>'+esc(x.owner)+' · '+esc(({evaluate:'评估',rewrite:'改写',create:'选题起稿'})[x.operation]||x.operation)+'</h2><p>'+esc(x.at)+' · '+esc(x.status)+' · 模拟耗时 '+x.durationMs+' ms</p></div></article>').join(''):'<div class="empty">当前范围暂无任务。完成或阻断一次操作后显示记录。</div>');}
$('#fill-sample').onclick=()=>{$('#material').value=inputType==='topic'?'面对变化，如何从一个小行动开始':C.sample;$('#requirements').value='保留核心意思，减少说教；不虚构吉利根原话。';$('#retain').value=inputType==='topic'?'先承认此刻的感受':'先承认此刻的感受';$('#scenario').value='available';notify('已填入合成材料；不是吉利根原话。');};
let usageMember='all',usageDays='all';
renderUsage=function(){const scoped=db.usage.filter(x=>x.business===business()&&(admin()||x.owner===user())),owners=[...new Set(scoped.map(x=>x.owner))];const cutoff=usageDays==='all'?0:Date.now()-Number(usageDays)*86400000;const rs=scoped.filter(x=>(usageMember==='all'||x.owner===usageMember)&&new Date(x.at).getTime()>=cutoff);$('#usage-page').innerHTML='<header class="page-header"><div><p class="eyebrow">仅本地演示统计</p><h1>使用情况</h1></div></header><p class="muted">'+(admin()?'演示管理员可看本业务成员':'成员仅看本人')+'；模拟任务不等于真实AI调用，费用未知不按0计算。</p><div class="filter-row content-panel"><label>成员<select id="usage-member"><option value="all">'+(admin()?'本业务所有成员':'本人')+'</option>'+owners.map(u=>'<option '+(usageMember===u?'selected':'')+'>'+esc(u)+'</option>').join('')+'</select></label><label>时间范围<select id="usage-days">'+[['all','全部'],['7','近7天'],['30','近30天']].map(([v,t])=>'<option value="'+v+'" '+(usageDays===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><div class="metric-grid"><div class="score-card"><h2>任务尝试</h2><strong>'+rs.length+'</strong></div><div class="score-card"><h2>完成</h2><strong>'+rs.filter(x=>x.status==='completed').length+'</strong></div><div class="score-card"><h2>阻断／失败</h2><strong>'+rs.filter(x=>x.status!=='completed').length+'</strong></div><div class="score-card"><h2>模型消耗</h2><strong>未调用</strong><p>Token未知；实际费用未知</p></div></div>'+ (rs.length?rs.map(x=>'<article class="history-row"><div><h2>'+esc(x.owner)+' · '+esc(({evaluate:'评估',rewrite:'改写',create:'选题起稿'})[x.operation]||x.operation)+'</h2><p>'+esc(x.at)+' · '+esc(x.status)+' · 模拟耗时 '+x.durationMs+' ms</p></div></article>').join(''):'<div class="empty">当前范围暂无任务。</div>');$('#usage-member').onchange=()=>{usageMember=$('#usage-member').value;renderUsage();};$('#usage-days').onchange=()=>{usageDays=$('#usage-days').value;renderUsage();};};
const flowShow=show;show=function(p){if(business()!=='gilligan'&&['knowledge','usage'].includes(p)){notify('当前选择Robert；吉利根资料不在其他业务下展示。');flowShow('creator');return;}flowShow(p);};
const businessChange=$('#business').onchange;$('#business').onchange=()=>{selectedRefs.clear();usageMember='all';businessChange();updateContext();};
const identityChange=$('#identity').onchange;$('#identity').onchange=()=>{usageMember='all';identityChange();};
const flowRenderResult=renderResult;
renderResult=function(){flowRenderResult();const r=current;if(!r)return;const card=$('#result-page .result-card');if(card&&r.versions?.length)card.insertAdjacentHTML('beforeend','<section class="revise"><h2>版本与报告历史</h2>'+r.versions.map(v=>'<details class="issue"><summary>第 '+v.version+' 版 · '+(v.stage==='assessment'?'评估报告':'历史内容')+'</summary>'+(v.assessment?assessment(v.assessment):'<p class="muted">该旧快照未记录评价报告。</p>')+'<div class="review-body">'+esc(v.content)+'</div></details>').join('')+'</section>');if($('#download'))$('#download').onclick=()=>{const report=r.stage==='assessment'?'# 两轴评价报告（模拟）\n\n学问忠实度：'+(r.assessment?.fidelity.level||'未评估')+'\n'+(r.assessment?.fidelity.reason||'')+'\n\n表达贴近度：'+(r.assessment?.expression.level||'未评估')+'\n'+(r.assessment?.expression.reason||'')+'\n\n逐句问题：\n'+(r.issues||[]).map(x=>x.fragment+'\n'+x.kind+'\n'+x.suggestion+'\n候选来源：'+x.source).join('\n\n'):r.content;const text='# '+r.title+'\n\n'+report+'\n\n## 来源说明（合成）\n'+r.sources.map(s=>s.title+' / '+s.locator+' / '+s.usage).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download='吉利根-'+(r.stage==='assessment'?'评估报告':'终稿')+'-v'+r.version+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};};
bindNavigation();setInputType('material');
